// expandEnv replaces ${NAME} and ${NAME:-fallback} with environment values
// and $$ with a literal $. Any other $ is kept.
func expandEnv(s string) (string, error) {
	if !strings.Contains(s, "$") {
		return s, nil
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] != '$' || i+1 >= len(s) {
			b.WriteByte(s[i])
			continue
		}
		switch s[i+1] {
		case '$':
			b.WriteByte('$')
			i++
		case '{':
			end := strings.IndexByte(s[i+2:], '}')
			if end < 0 {
				return "", fmt.Errorf("unterminated ${ in value")
			}
			ref := s[i+2 : i+2+end]
			name, fallback, hasFallback := strings.Cut(ref, ":-")
			v := os.Getenv(name)
			if v == "" {
				if !hasFallback {
					if _, set := os.LookupEnv(name); !set {
						return "", fmt.Errorf("undefined variable %q", name)
					}
				}
				v = fallback
			}
			b.WriteString(v)
			i += 2 + end
		default:
			b.WriteByte('$')
		}
	}
	return b.String(), nil
}''')
